python3 -c "
import json
with open('/app/resources/treasury_bulletin_2024_12.json', 'r') as f:
    data = json.load(f)

# Find keys containing 'Department of Commerce'
def find_keys(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            new_path = f'{path}.{k}' if path else k
            if 'Department of Commerce' in str(k):
                print(f'Key: {new_path}')
            find_keys(v, new_path)
    elif isinstance(obj, list) and len(obj) > 0:
        find_keys(obj[0], f'{path}[0]')

find_keys(data)
"

